import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

constexpr int OC_TILE = 4;
__global__ void conv3d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    const int N, const int C_in, const int D, const int H, const int W,
    const int C_out, const int K,
    const int D_out, const int H_out, const int W_out,
    const int stride, const int padding, const int dilation,
    const int groups, const int C_in_per_group, const int C_out_per_group,
    const int TILE_D, const int TILE_H, const int TILE_W,
    const int TID, const int TIH, const int TIW,
    const int numTilesD, const int numTilesH, const int numTilesW)
{
    extern __shared__ float smem[];
    float* smem_input = smem;
    float* smem_weight = smem_input + (long)C_in_per_group * TID * TIH * TIW;
    const int tile_idx = blockIdx.x;
    const int tw_idx = tile_idx % numTilesW;
    const int th_idx = (tile_idx / numTilesW) % numTilesH;
    const int td_idx = tile_idx / (numTilesW * numTilesH);
    const int od0 = td_idx * TILE_D;
    const int oh0 = th_idx * TILE_H;
    const int ow0 = tw_idx * TILE_W;
    const int n = blockIdx.y;
    const int g = blockIdx.z;
    const int ic_start = g * C_in_per_group;
    const int oc_start = g * C_out_per_group;
    const int id0 = od0 * stride - padding;
    const int ih0 = oh0 * stride - padding;
    const int iw0 = ow0 * stride - padding;
    const int tid = threadIdx.x;
    const int block_threads = blockDim.x;
    const long input_tile_elems = (long)C_in_per_group * TID * TIH * TIW;
    for (long e = tid; e < input_tile_elems; e += block_threads) {
        long tmp = e;
        const int zw = tmp % TIW; tmp /= TIW;
        const int zh = tmp % TIH; tmp /= TIH;
        const int zd = tmp % TID; tmp /= TID;
        const int c = tmp;
        const int id = id0 + zd;
        const int ih = ih0 + zh;
        const int iw = iw0 + zw;
        const int ic = ic_start + c;
        float val = 0.0f;
        if (id >= 0 && id < D && ih >= 0 && ih < H && iw >= 0 && iw < W) {
            val = input[(((long)n * C_in + ic) * D + id) * H * W + (long)ih * W + iw];
        }
        smem_input[e] = val;
    }
    __syncthreads();
    const int tw = tid % TILE_W;
    const int th = (tid / TILE_W) % TILE_H;
    const int td = tid / (TILE_W * TILE_H);
    const int od = od0 + td;
    const int oh = oh0 + th;
    const int ow = ow0 + tw;
    const bool valid_out = (td < TILE_D) && (th < TILE_H) && (tw < TILE_W) &&
                            (od < D_out) && (oh < H_out) && (ow < W_out);
    const long weight_tile_elems = (long)C_in_per_group * K * K * K;
    const long weight_tile_elems_full = weight_tile_elems * OC_TILE;
    for (int oc_local = 0; oc_local < C_out_per_group; oc_local += OC_TILE) {
        for (long e = tid; e < weight_tile_elems_full; e += block_threads) {
            const int oc_offset = (int)(e / weight_tile_elems);
            const long e_local = e % weight_tile_elems;
            const int oc_actual_local = oc_local + oc_offset;
            if (oc_actual_local < C_out_per_group) {
                long tmp = e_local;
                const int kw = tmp % K; tmp /= K;
                const int kh = tmp % K; tmp /= K;
                const int kd = tmp % K; tmp /= K;
                const int c = tmp;
                const int oc = oc_start + oc_actual_local;
                smem_weight[e] = weight[(((long)oc * C_in_per_group + c) * K + kd) * K * K + kh * K + kw];
            } else {
                smem_weight[e] = 0.0f;
            }
        }
        __syncthreads();
        if (valid_out) {
            float acc[OC_TILE];
            #pragma unroll
            for (int t = 0; t < OC_TILE; ++t) acc[t] = 0.0f;
            for (int c = 0; c < C_in_per_group; ++c) {
                const float* in_c = smem_input + (long)c * TID * TIH * TIW;
                for (int kd = 0; kd < K; ++kd) {
                    const int zd = td * stride + kd * dilation;
                    const float* in_d = in_c + (long)zd * TIH * TIW;
                    for (int kh = 0; kh < K; ++kh) {
                        const int zh = th * stride + kh * dilation;
                        const float* in_h = in_d + (long)zh * TIW;
                        for (int kw = 0; kw < K; ++kw) {
                            const int zw = tw * stride + kw * dilation;
                            const float in_val = in_h[zw];
                            const long widx = ((long)c * K + kd) * K * K + kh * K + kw;
                            #pragma unroll
                            for (int t = 0; t < OC_TILE; ++t) {
                                acc[t] += in_val * smem_weight[(long)t * weight_tile_elems + widx];
                            }
                        }
                    }
                }
            }
            #pragma unroll
            for (int t = 0; t < OC_TILE; ++t) {
                const int oc_actual_local = oc_local + t;
                if (oc_actual_local < C_out_per_group) {
                    const int oc = oc_start + oc_actual_local;
                    output[(((long)n * C_out + oc) * D_out + od) * H_out * W_out + (long)oh * W_out + ow] = acc[t];
                }
            }
        }
        __syncthreads();
    }
}
torch::Tensor conv3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    int stride,
    int padding,
    int dilation,
    int groups)
{
    input = input.contiguous();
    weight = weight.contiguous();
    const int N = input.size(0);
    const int C_in = input.size(1);
    const int D = input.size(2);
    const int H = input.size(3);
    const int W = input.size(4);
    const int C_out = weight.size(0);
    const int C_in_per_group = weight.size(1);
    const int K = weight.size(2);
    const int C_out_per_group = C_out / groups;
    const int D_out = (D + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int H_out = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int W_out = (W + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    auto output = torch::empty({N, C_out, D_out, H_out, W_out}, input.options());
    const int TILE_D = 4;
    const int TILE_H = 8;
    const int TILE_W = 8;
    const int TID = (TILE_D - 1) * stride + (K - 1) * dilation + 1;
    const int TIH = (TILE_H - 1) * stride + (K - 1) * dilation + 1;
    const int TIW = (TILE_W - 1) * stride + (K - 1) * dilation + 1;
    const int numTilesD = (D_out + TILE_D - 1) / TILE_D;
    const int numTilesH = (H_out + TILE_H - 1) / TILE_H;
    const int numTilesW = (W_out + TILE_W - 1) / TILE_W;
    const int threads = TILE_D * TILE_H * TILE_W;
    dim3 blocks((unsigned int)(numTilesD * numTilesH * numTilesW), (unsigned int)N, (unsigned int)groups);
    const size_t smem_bytes = ((size_t)C_in_per_group * TID * TIH * TIW +
                               (size_t)C_in_per_group * K * K * K * OC_TILE) * sizeof(float);
    if (smem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(conv3d_forward_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
    }
    conv3d_forward_kernel<<<blocks, threads, smem_bytes>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, D, H, W,
        C_out, K,
        D_out, H_out, W_out,
        stride, padding, dilation,
        groups, C_in_per_group, C_out_per_group,
        TILE_D, TILE_H, TILE_W,
        TID, TIH, TIW,
        numTilesD, numTilesH, numTilesW
    );
    return output;
}
"""

conv3d_cpp_source = r"""
torch::Tensor conv3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    int stride,
    int padding,
    int dilation,
    int groups);
"""

conv3d_ext = load_inline(
    name="conv3d_ext",
    cpp_sources=conv3d_cpp_source,
    cuda_sources=conv3d_source,
    functions=["conv3d_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a standard 3D convolution operation with square input and square kernel,
    using a custom CUDA kernel for the forward computation.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.use_bias = bias

        self.weight = nn.Parameter(torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size, kernel_size))
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        if bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.cuda().contiguous()

        out = conv3d_ext.conv3d_forward(
            x, weight,
            self.stride, self.padding, self.dilation, self.groups
        )

        if self.use_bias:
            out = out + self.bias.view(1, -1, 1, 1, 1)

        return out


batch_size = 16
in_channels = 3
out_channels = 64
kernel_size = 3
depth = 64
width = 64
height = 64


def get_inputs():
    x = torch.rand(batch_size, in_channels, depth, width, height)
    return [x]


def get_init_inputs():
    return [in_channels, out_channels, kernel_size]

